import gzip,csv
def rd(p):
  return {int(r["t_open_ms"]):r for r in csv.DictReader(gzip.open(p,"rt"))}
g=rd("gate-futures_usdt/BTC_USDT.csv.gz"); b=rd("bybit-linear/BTCUSDT.csv.gz"); gs=rd("gate-spot/ETH_USDT.csv.gz"); bs=rd("bybit-spot/ETHUSDT.csv.gz")
for nm,a,c in (("btc fut",g,b),("eth spot",gs,bs)):
  k=sorted(set(a)&set(c)); d=sorted(abs(float(a[t]["c"])/float(c[t]["c"])-1)*1e4 for t in k)
  print(nm,len(a),len(c),len(k),"med bp",round(d[len(d)//2],2),"p99",round(d[int(len(d)*.99)],2), "min t",min(a),max(a))
  t=k[20000]; print(" ",a[t]); print(" ",c[t])
E'

